// Ambient types for the virtual modules generated by @morphkit/vite-plugin.
// Add `"types": ["@morphkit/vite-plugin/client"]` to the app tsconfig.

declare module 'virtual:morphkit/manifest' {
  interface ManifestFile {
    path: string
    source: string
  }
  const manifest: {
    version: 1
    dynamicRoots: string[]
    dynamic: ManifestFile[]
    readonly: ManifestFile[]
    coreTypes: ManifestFile[]
    externals: string[]
    externalPatterns: string[]
    alias: Record<string, string>
  }
  export default manifest
}

declare module 'virtual:morphkit/externals' {
  const externals: Record<string, Record<string, unknown>>
  export default externals
}

declare module 'virtual:morphkit/fallback' {
  const fallback: Record<string, Record<string, unknown>>
  export default fallback
}

declare module 'virtual:morphkit/wasm-url' {
  const wasmURL: string | null
  export default wasmURL
}

declare module 'virtual:morphkit' {
  export { default as manifest } from 'virtual:morphkit/manifest'
  export { default as externals } from 'virtual:morphkit/externals'
  export { default as fallback } from 'virtual:morphkit/fallback'
  export { default as wasmURL } from 'virtual:morphkit/wasm-url'
}
